WITH joined_data AS (SELECT s.cds, s.avgscrread, s.avgscrmath, s.avgscrwrite, s.rtype, s.enroll12, sc.fundingtype, sc.cdscode FROM satscores s JOIN schools sc ON s.cds = sc.cdscode JOIN frpm f ON f.cdscode = sc.cdscode WHERE s.enroll12 IS NOT NULL AND sc.fundingtype IS NOT NULL) SELECT fundingtype, AVG(avgscrread) as avg_read, AVG(avgscrmath) as avg_math, AVG(avgscrwrite) as avg_write, AVG(enroll12) as avg_enrollment FROM joined_data GROUP BY fundingtype;
